import pandas as pd
import numpy as np

# Load the datasets
gas_waste_data = pd.read_csv('chunks_csv/bivariate/bivariate_2023_gas_waste.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Data Validation: Check for missing values
if gas_waste_data.isnull().any().any() or adjacency_data.isnull().any().any():
    raise ValueError("Missing values detected in the datasets.")

# Create a mapping of each borough to its geographic neighbors
neighbors = {}
for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors:
        neighbors[borough] = []
    neighbors[borough].append(neighbor)

# Calculate Lee's L statistic
def calculate_lees_l(gas_values, waste_values):
    mean_gas = np.mean(gas_values)
    mean_waste = np.mean(waste_values)
    n = len(gas_values)
    if n == 0:
        return np.nan
    return np.sum((gas_values - mean_gas) * (waste_values - mean_waste)) / (n * np.std(gas_values) * np.std(waste_values))

# Prepare data for analysis
data_points_used = 0
observed_lees_l = []

for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
    if borough in neighbors:
        neighbor_waste_values = gas_waste_data[gas_waste_data['borough'].isin(neighbors[borough])]['Waste_value']
        if not neighbor_waste_values.empty:
            data_points_used += 1
            observed_lees_l.append(calculate_lees_l(np.array([gas_value]), neighbor_waste_values.to_numpy()))

# Calculate the observed Lee's L statistic
observed_lees_l_statistic = np.mean(observed_lees_l)

# Perform Randomization Test
n_permutations = 500
permuted_lees_l_stats = []

for _ in range(n_permutations):
    permuted_waste_values = np.random.permutation(gas_waste_data['Waste_value'].to_numpy())
    permuted_lees_l = []

    for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
        if borough in neighbors:
            neighbor_waste_values = permuted_waste_values[gas_waste_data['borough'].isin(neighbors[borough]).to_numpy()]
            if neighbor_waste_values.size > 0:
                permuted_lees_l.append(calculate_lees_l(np.array([gas_value]), neighbor_waste_values))

    permuted_lees_l_stats.append(np.mean(permuted_lees_l))

# Calculate p-value
p_value = np.sum(np.array(permuted_lees_l_stats) >= observed_lees_l_statistic) / n_permutations

# Determine the verdict
if p_value < 0.05:
    if observed_lees_l_statistic > 0:
        verdict = "POSITIVE"
    else:
        verdict = "NEGATIVE"
else:
    verdict = "NOT SIGNIFICANT"

# Print results
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {verdict} (test statistic = {observed_lees_l_statistic}, p = {p_value})")
